def main():
    shot = sys.argv[1] if len(sys.argv) > 1 else "R00"
    if shot not in SHOTS:
        raise SystemExit(f"unknown shot: {shot}")
    base_name, first_frame, title = SHOTS[shot]
    base = json.loads((WF_DIR / base_name).read_text(encoding="utf-8"))
    base["3"]["inputs"]["noise_seed"] = 261000000 + int(shot[1:])
    base["7"]["inputs"]["length"] = 195
    base["7"]["inputs"]["first_frame"] = ["20", 0]
    base["7"]["inputs"]["prompt"] = PROMPTS[shot]
    base["14"]["inputs"]["filename_prefix"] = f"逍遥仙重制/{shot}_{title}_PDD8"
    base["20"]["inputs"]["image"] = f"逍遥仙/关键帧/{first_frame}"
    base.pop("6", None)
    base["12"]["inputs"].pop("audio", None)
    base.pop("12", None)
    base["13"]["inputs"].pop("audio", None)
    workflow_path = WF_DIR / f"{shot}_I2VA_PDD8_dynamic_api.json"
    workflow_path.write_text(json.dumps(base, ensure_ascii=False, indent=2), encoding="utf-8")
    requests.get(API + "/system_stats", timeout=5).raise_for_status()
    result = requests.post(API + "/prompt", json={"prompt": base, "client_id": str(uuid.uuid4())}, timeout=60)
    result.raise_for_status()
    payload = result.json()
    (CHECK / f"{shot}_submit.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps({"shot": shot, "workflow": str(workflow_path), **payload}, ensure_ascii=False))

if __name__ == "__main__":
    main()
